/* Shared supplied-event catalogue and assessment for Prediction and Event Promise. */
(function(root){'use strict';
const DATA=root.KPEventHouseData,$=id=>root.document?.getElementById(id),lang=()=>root.KPPreferences?.get?.().language||'english',entry=id=>DATA.entries.find(e=>String(e.id)===String(id));
const display=(text,language)=>language==='marathi'?String(text).replace(/\([^()]*[A-Za-z][^()]*\)/g,'').replace(/\bCA\b/g,'सनदी लेखापाल').replace(/\bKP\b/g,'केपी').trim():text;
const label=e=>lang()==='marathi'?(e.event.mr||e.event.en||''):(e.event.en||e.event.mr||'');
function events(language=lang()){return DATA.entries.filter(r=>language==='bilingual'||r.language===language).map(r=>({id:r.id,event:{[r.language==='marathi'?'mr':'en']:display(r.matter,r.language)},category:r.category,mainHouses:[...r.mainHouses],supportingGroups:r.supportingGroups.map(g=>[...g]),relevantHouses:[...new Set(r.supportingGroups.flat())],automaticEligible:Boolean(r.mainHouses.length&&(r.supportingGroups.length||r.cslPlanet)&&!r.extraConditions&&!r.sensitiveReference),remarks:r.extraConditions?display(r.supportingRaw,r.language):'',promiseRaw:r.supportingRaw,promiseMode:'joint-group',issues:r.extraConditions?['additional-source-conditions-require-review']:[],sourceKind:'uploaded-event-house',sourceRow:r.sourceRow,sources:{[r.language==='marathi'?'mr':'en']:{filename:r.sourceFilename,row:r.sourceRow,main:r.primaryRaw,supporting:r.supportingRaw}}}));}
function assess(data){const r=entry(data?.rule?.id);if(!r)return null;const mr=lang()==='marathi',say=(en,ma)=>mr?ma:en;
 if(!data.ready)return {promised:false,incomplete:true,reason:say('Complete the chart.','कुंडली पूर्ण करा.')};
 if(!r.mainHouses.length)return {promised:false,pending:true,qualified:true,reason:say('The source does not specify a primary cusp. Review its stated conditions before assigning a promise.','स्रोतात मुख्य भाव दिलेला नाही. वचन ठरवण्यापूर्वी दिलेल्या अटी तपासाव्यात.')};
 if(!r.mainHouses.includes(data.cusp))return {promised:false,reason:say('Select a primary cusp listed in this source rule.','या नियमात दिलेला मुख्य भाव निवडा.')};
 const csl=data.layers?.find(l=>l.role==='CSL')?.id;
 if(r.cslPlanet&&!csl)return {promised:false,pending:true,qualified:true,reason:say('This cusp sub-lord condition needs the cusp-chain data; a DBA house group alone cannot decide it.','या भाव उपस्वामीच्या अटीसाठी भावस्वामी साखळी आवश्यक; केवळ दशेचा भावगट पुरेसा नाही.')};
 if(r.cslPlanet){const matched=csl===r.cslPlanet;return {promised:matched&&!r.sensitiveReference,pending:matched&&r.sensitiveReference,qualified:r.sensitiveReference,reason:say('Specified cusp sub-lord condition '+(matched?'matched.':'did not match.'),'नमूद भाव उपस्वामीची अट '+(matched?'जुळली.':'जुळली नाही.'))};}
 const best=(data.proofs||[]).filter(p=>p.required?.length).sort((a,b)=>(b.matched?.length||0)/b.required.length-(a.matched?.length||0)/a.required.length)[0];
 if(!best)return {promised:false,pending:true,qualified:true,reason:say('This is a narrative/planet/sign condition without a complete numeric house group; review is required.','हा पूर्ण संख्यात्मक भावगट नसलेला वर्णनात्मक, ग्रह किंवा राशीविषयक नियम आहे; अटी तपासाव्यात.')};
 const ratio=best.matched.length/best.required.length,promised=ratio===1&&!r.extraConditions&&!r.sensitiveReference,qualified=r.extraConditions||r.sensitiveReference||ratio<1;
 return {promised,qualified,pending:ratio===1&&Boolean(r.extraConditions||r.sensitiveReference),coverage:ratio,basis:'exact-uploaded-house-group',reason:say('Exact house match required. House support: '+best.matched.length+'/'+best.required.length+'; matched '+(best.matched.join(', ')||'none')+'; missing '+(best.missing.join(', ')||'none')+'. '+(r.extraConditions?'Additional source conditions remain for review: '+r.supportingRaw+'. ':'')+'This is traditional rule support, not confirmation of the event.','पूर्ण भावगट जुळणे आवश्यक. भावांचा आधार: '+best.matched.length+'/'+best.required.length+'; जुळलेले '+(best.matched.join(', ')||'नाही')+'; उरलेले '+(best.missing.join(', ')||'नाही')+'. '+(r.extraConditions?'अतिरिक्त अटी तपासाव्यात: '+display(r.supportingRaw,'marathi')+'. ':'')+'हा पारंपरिक नियमांचा आधार आहे; घटनेची खात्री नाही.')};
}
function select(id){const e=events().find(e=>String(e.id)===String(id));if(!e||!$('ep-event'))return false;let cusp=Number($('ep-cusp').value)||1;if(e.mainHouses.length&&!e.mainHouses.includes(cusp))cusp=e.mainHouses[0];$('ep-category').value='0';$('ep-search').value='';root.KPEventPromise.refresh(true);if(![...$('ep-event').options].some(o=>o.value===String(id)))$('ep-event').append(new Option(label(e),String(id)));$('ep-auto-cusp').checked=false;$('ep-cusp').value=String(cusp);$('ep-event').value=String(id);$('ep-event').dispatchEvent(new Event('change',{bubbles:true}));root.KPEventPromise.refresh(true);return true;}
function controls(active){const selectBox=$('pred-house-event');if(!selectBox)return;const list=events(),signature=lang()+'|'+list.length;if(selectBox.dataset.sourceSignature!==signature){const previous=selectBox.value;selectBox.replaceChildren(...list.map(e=>new Option(label(e),String(e.id))));if(list.some(e=>String(e.id)===previous))selectBox.value=previous;selectBox.dataset.sourceSignature=signature;}if(active&&list.some(e=>String(e.id)===$('ep-event')?.value))selectBox.value=$('ep-event').value;if(active&&selectBox.value&&$('ep-event')?.value!==selectBox.value)select(selectBox.value);}
function match(model=root.currentKPModel,id=$('pred-house-event')?.value){const r=entry(id),e=events().find(e=>String(e.id)===String(id)),mr=lang()==='marathi';if(!r||!e)return {ready:false,rows:[],reason:mr?'दिलेल्या तक्त्यातील घटना निवडा.':'Select an event from the supplied table.'};if(!model?.ready)return {ready:false,rows:[],reason:mr?'जन्मकुंडली पूर्ण करा.':'Complete the natal chart.'};const current=root.KPEventPromise.getData(),data=String(current?.rule?.id)===String(id)?current:root.KPEventPromise.analyze(model,{event:e,cusp:e.mainHouses[0]||Number($('ep-cusp')?.value)||1,method:$('ep-method')?.value||'fourfold',layers:['CSL','STL','SBL']}),verdict=assess(data),heading=verdict.pending?(mr?'अटींची पडताळणी आवश्यक':'Conditions require review'):verdict.promised?(mr?'पारंपरिक भावाधार अनुकूल':'Traditional house support is favorable'):(mr?'पुरेसा भावाधार नाही':'Insufficient house support');return {ready:data.ready,reason:data.reason,rows:[{id:'event-house-'+id,language:r.language,title:display(r.matter,r.language),text:heading+'\n'+verdict.reason,status:verdict.pending?'review':verdict.promised?'matched':'unmatched'}],verdict,analysis:data,eventId:r.id};}
function install(){if(!root.KPHandbook)return;const old=root.KPHandbook;root.KPHandbook=Object.freeze({...old,getCatalogue(){const base=old.getCatalogue();return {...base,events:[...base.events,...events()],metadata:{...base.metadata,uploadedEventSources:DATA.metadata.sources}};}});}
root.KPEventHouseRules=Object.freeze({events,entry,assess,select,controls,match});if(root.document)install();if(typeof module!=='undefined'&&module.exports)module.exports=root.KPEventHouseRules;
})(typeof window==='undefined'?globalThis:window);
